 for annex in corpus["annexes"].as_array().unwrap(){for case in corpus["cases"].as_array().unwrap(){
  let mut snapshot=if let Some(word)=case["word"].as_str(){every_word(u64::from_str_radix(word,16).unwrap())}else{fixture()};
