   let restored=En1997Snapshot::decode_sqlite_snapshot_native(&ordinary,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(project(&restored),project(&snapshot));
   for(budget,kind)in[(SqliteDatabaseLimits{max_value_bytes:bytes-1,..limits},semio_framework_value::ValueRefusalKind::OwnershipLimit),(SqliteDatabaseLimits{max_rows:rows-1,..limits},semio_framework_value::ValueRefusalKind::WorkLimit)]{
